import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.CS-cBh1g.js";const g=JSON.parse('{"title":"Connect an agent","description":"","frontmatter":{},"headers":[],"relativePath":"agents/index.md","filePath":"agents/index.md"}'),o={name:"agents/index.md"};function i(r,t,h,d,l,c){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="connect-an-agent" tabindex="-1">Connect an agent <a class="header-anchor" href="#connect-an-agent" aria-label="Permalink to &quot;Connect an agent&quot;">​</a></h1><p>A coding agent (Claude Code, Codex or any agent that can run commands) works in its own chat: you tell it what the robot should do differently, it changes the code. Mayhem is where you check what it did, by what the robot does rather than by reading the diff. People stay in charge of the decision that matters: whether a change goes into <code>main</code> and onto the robot.</p><h2 id="make-its-work-show-up-ready-to-review" tabindex="-1">Make its work show up ready to review <a class="header-anchor" href="#make-its-work-show-up-ready-to-review" aria-label="Permalink to &quot;Make its work show up ready to review&quot;">​</a></h2><ol><li>In the app, choose the robot code folder.</li><li>Open <strong>Settings → Agents and the project file → Tell your agent once</strong> and copy the text. It has this robot&#39;s folder filled in.</li><li>Paste it into your agent&#39;s chat, or into the robot repo&#39;s <code>CLAUDE.md</code> or <code>AGENTS.md</code>.</li></ol><p>From then on the agent works on a branch, checks its own change with Mayhem&#39;s tools, and records a sim proof on its commit. The branch appears under <strong>Changes → To review</strong> with its risk and that proof. See <a href="/Mayhem/agents/review">How changes get reviewed</a>.</p><h2 id="give-it-mayhem-s-tools-mcp" tabindex="-1">Give it Mayhem&#39;s tools (MCP) <a class="header-anchor" href="#give-it-mayhem-s-tools-mcp" aria-label="Permalink to &quot;Give it Mayhem&#39;s tools (MCP)&quot;">​</a></h2><p>The agent works best with Mayhem&#39;s tools: analyzing logs, running the sim proof, diffing behavior. Add the Mayhem MCP server to your agent&#39;s configuration:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-dark github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">    &quot;mayhem&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#79B8FF;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;/absolute/path/to/Mayhem/scripts/mayhem.mjs&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#9ECBFF;--shiki-dark:#9ECBFF;">&quot;mcp&quot;</span><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#E1E4E8;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use the path to a Mayhem checkout or to the extracted <code>Mayhem-suite-tools</code> folder from a release. It needs Node 24 or later. <strong>Settings → Agents and the project file → Connect over MCP</strong> shows the same setup.</p><p>Agents without MCP can call every tool from the shell: <code>node scripts/mayhem.mjs tool &lt;name&gt; &#39;&lt;JSON&gt;&#39;</code>. See <a href="/Mayhem/agents/tools">Command line and MCP tools</a>.</p><h2 id="other-panels-under-agents-and-the-project-file" tabindex="-1">Other panels under Agents and the project file <a class="header-anchor" href="#other-panels-under-agents-and-the-project-file" aria-label="Permalink to &quot;Other panels under Agents and the project file&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Panel</th><th>Use</th></tr></thead><tbody><tr><td><strong>Share this project with an agent</strong></td><td>A brief describing the project, for a one-off request (&quot;add a second auto&quot;).</td></tr><tr><td><strong>Live file link</strong></td><td><strong>Save project file</strong> links the project to <code>robot.mayhem.json</code>, so an agent&#39;s edits show up in the app within a second.</td></tr><tr><td><strong>Command line</strong></td><td>The <code>scripts/mayhem.mjs</code> commands.</td></tr><tr><td><strong>C++ library</strong></td><td>Export the routines as a C++ header.</td></tr><tr><td><strong>Project document</strong></td><td>The raw project JSON.</td></tr></tbody></table><h2 id="what-agents-can-and-can-t-do" tabindex="-1">What agents can and can&#39;t do <a class="header-anchor" href="#what-agents-can-and-can-t-do" aria-label="Permalink to &quot;What agents can and can&#39;t do&quot;">​</a></h2><ul><li>They <strong>can</strong> edit robot code, the project file, machines and scenarios; run the simulation; read logs; and commit on their own branch.</li><li>They <strong>can&#39;t</strong> command the robot. Mayhem only reads NetworkTables, and the MCP tools never deploy.</li><li>They <strong>don&#39;t</strong> push to <code>main</code>. <code>main</code> is the known-good version, and putting it back on the robot is a button only people press.</li></ul><p>After an agent edits a routine, look at the field and the graph, and preview it before running it on the robot.</p>`,15)])])}const k=e(o,[["render",i]]);export{g as __pageData,k as default};
